import { useEffect, useMemo, useRef, useState } from "react";

import {
  ChevronLeft,
  ChevronRight,
  SkipForward,
  ArrowRightCircle,
  Loader2,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Progress } from "@/components/ui/progress";

import { useInterviewContext } from "@/interview/context/InterviewContext";

function getAnswerForQuestion(session, questionId) {
  if (!session?.answers?.length || !questionId) return null;
  return session.answers.find((a) => a.questionId === questionId) || null;
}

export default function InterviewPracticePage() {

  const { currentSession, currentQuestion,sessionStatus, navigation, session } =
    useInterviewContext();

  const textareaRef = useRef(null);
  const [localValue, setLocalValue] = useState("");

  const currentIndex = useMemo(() => {
    if (!currentSession?.currentQuestionId) return -1;
    return currentSession.questionIds.indexOf(currentSession.currentQuestionId);
  }, [currentSession]);

  const total = currentSession?.questionIds?.length ?? 0;
  const questionNumber = currentIndex >= 0 ? currentIndex + 1 : 0;

  const existingAnswer = useMemo(() => {
    if (!currentSession?.currentQuestionId) return null;
    return getAnswerForQuestion(currentSession, currentSession.currentQuestionId);
  }, [currentSession]);
  console.log("Current Answer:", existingAnswer);

  useEffect(() => {
  if (!currentSession?.currentQuestionId) {
    setLocalValue("");
    return;
  }

  const answer = getAnswerForQuestion(
    currentSession,
    currentSession.currentQuestionId
  );

  setLocalValue(answer?.answer ?? "");
}, [currentSession?.currentQuestionId, currentSession]);

  useEffect(() => {
    const el = textareaRef.current;
    if (!el) return;

    // auto-resize
    el.style.height = "0px";
    el.style.height = `${el.scrollHeight}px`;
  }, [localValue]);

  const [isFinishing, setIsFinishing] = useState(false);

  const completedCount = useMemo(() => {
  if (!currentSession?.questionIds?.length) return 0;

  return currentSession.questionIds.filter((qid) => {
    const answer = getAnswerForQuestion(currentSession, qid);

    return (
      answer &&
      !answer.skipped &&
      answer.answer?.trim().length > 0
    );
  }).length;
}, [currentSession]);

const skippedCount = useMemo(() => {
  if (!currentSession?.questionIds?.length) return 0;

  return currentSession.questionIds.filter((qid) => {
    const answer = getAnswerForQuestion(currentSession, qid);
    return answer?.skipped;
  }).length;
}, [currentSession]);

const remainingCount = useMemo(() => {
  return total - completedCount - skippedCount;
}, [total, completedCount, skippedCount]);

const percentComplete = useMemo(() => {
  if (!total) return 0;
  return Math.round((completedCount / total) * 100);
}, [completedCount, total]);

  // Avoid permanently entering loading state: consider session ready
  // if we have a questionIds array even when currentQuestion is temporarily unresolved.
  const isLoading = !currentSession || !Array.isArray(currentSession.questionIds);




  const canGoPrevious = !!currentSession && currentIndex > 0;
  const canGoNext = !!currentSession && currentIndex >= 0 && currentIndex < total - 1;
  const canFinish = !!currentSession && currentIndex === total - 1 && total > 0;

  function handleSaveCurrentAnswer(nextText) {
    if (!currentSession?.currentQuestionId) return;
    session.submitAnswer({ questionId: currentSession.currentQuestionId, responseText: nextText });
  }

  function handlePrevious() {
    if (!canGoPrevious) return;
    handleSaveCurrentAnswer(localValue);
    navigation.goToPreviousQuestion();
  }

  function handleNext() {
    if (!canGoNext) return;
    handleSaveCurrentAnswer(localValue);
    navigation.goToNextQuestion();
  }

  function handleSkip() {
  navigation.skipCurrentQuestion(localValue);
}

  async function handleFinish() {
    if (!canFinish || isFinishing) return;
    setIsFinishing(true);
    try {
      handleSaveCurrentAnswer(localValue);
      session.finishSession();
      // No navigation to Results in Phase 3.
      session.generateSummary?.();
    } finally {
      setIsFinishing(false);
    }
  }

  const categoryLabel = currentQuestion?.category ?? "";
  const difficultyLabel = currentQuestion?.difficulty ?? "";

  if (isLoading) {
    return (
      <div className="w-full px-2 sm:px-0">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Loader2 className="size-4 animate-spin" aria-hidden="true" />
              Loading interview…
            </CardTitle>
          </CardHeader>
          <CardContent className="text-sm text-muted-foreground">Preparing questions.</CardContent>
        </Card>
      </div>
    );
  }

  if (!currentQuestion) {
    return (
      <div className="w-full px-2 sm:px-0">
        <Card>
          <CardHeader>
            <CardTitle>Empty state</CardTitle>
          </CardHeader>
          <CardContent className="text-sm text-muted-foreground">
            No active interview question. Start an interview from the setup wizard.
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="w-full px-2 sm:px-0">
      <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4 mb-4">
        <div className="space-y-1">
          <h1 className="text-xl sm:text-2xl font-semibold">Interview Practice</h1>
          <div className="text-sm text-muted-foreground">
            {`Question ${questionNumber} of ${total}`}
          </div>
        </div>

        <div className="flex items-center gap-2">
          {categoryLabel ? <Badge variant="secondary">{categoryLabel}</Badge> : null}
          {difficultyLabel ? <Badge variant="outline">{difficultyLabel}</Badge> : null}
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-base">{currentQuestion.prompt}</CardTitle>
        </CardHeader>

        <CardContent className="space-y-6">
          <div className="space-y-2">
            <div className="flex items-center justify-between gap-2 text-sm">
              <div className="font-medium">Progress</div>
              <div className="text-muted-foreground">
                {completedCount} completed • {skippedCount} skipped • {remainingCount} remaining • {percentComplete}%
              </div>
            </div>
            <Progress value={percentComplete} aria-label="Interview progress" />
          </div>

          <div className="space-y-2">
            <div className="text-sm font-medium">Your answer</div>
            <Textarea
              ref={textareaRef}
              value={localValue}
              onChange={(e) => setLocalValue(e.target.value)}
              placeholder="Write your answer here…"
              className="min-h-28 resize-none"
              aria-label="Answer editor"
            />
            <div className="text-xs text-muted-foreground flex items-center justify-between">
              <span>{sessionStatus === "in_progress" ? "" : ""}</span>
              <span>{localValue.length} characters</span>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-2 sm:items-center sm:justify-between">
            <div className="flex flex-wrap gap-2">
              <Button type="button" variant="outline" onClick={handlePrevious} disabled={!canGoPrevious}>
                <ChevronLeft className="mr-2 size-4" aria-hidden="true" />
                Previous
              </Button>

              <Button type="button" variant="outline" onClick={handleNext} disabled={!canGoNext}>
                Next
                <ChevronRight className="ml-2 size-4" aria-hidden="true" />
              </Button>

              <Button type="button" variant="secondary" onClick={handleSkip}>
                <SkipForward className="mr-2 size-4" aria-hidden="true" />
                Skip Question
              </Button>
            </div>

            <div className="flex flex-wrap gap-2">
              <Button type="button" onClick={handleFinish} disabled={!canFinish || isFinishing}>
                <ArrowRightCircle className="mr-2 size-4" aria-hidden="true" />
                {isFinishing ? "Finishing…" : "Finish Interview"}
              </Button>
            </div>
          </div>

          <div className="text-xs text-muted-foreground" aria-live="polite">
            Completed: {completedCount}/{total}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useMemo } from "react";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";

import { useInterviewContext } from "@/interview/context/InterviewContext";

function formatEpochMs(epochMs) {
  if (!epochMs || typeof epochMs !== "number") return "—";

  try {
    return new Date(epochMs).toLocaleString();
  } catch {
    return "—";
  }
}

function formatDurationMs(durationMs) {
  if (!durationMs || typeof durationMs !== "number" || durationMs < 0) return "—";

  const totalSeconds = Math.floor(durationMs / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) return `${hours}h ${minutes}m ${seconds}s`;
  if (minutes > 0) return `${minutes}m ${seconds}s`;
  return `${seconds}s`;
}

export default function InterviewResultsPage() {
  const { currentSession, questionBank, session } = useInterviewContext();

  const summary = useMemo(() => {
    // Must be presentation-only: compute from existing architecture.
    return session.generateSummary?.() ?? null;
  }, [session, currentSession, questionBank]);

  const sessionMeta = summary;
  const summaryQuestions = sessionMeta?.questions ?? [];

  const total = summaryQuestions.length;
  const skipped = summaryQuestions.filter((q) => q.skipped).length;
  const answered = summaryQuestions.filter((q) => !q.skipped && String(q.answerText ?? "").trim().length > 0)
    .length;

  const completionPct = total > 0 ? Math.round((answered / total) * 100) : 0;
  const durationMs =
    typeof sessionMeta?.startedAtEpochMs === "number" &&
    typeof sessionMeta?.finishedAtEpochMs === "number"
      ? sessionMeta.finishedAtEpochMs - sessionMeta.startedAtEpochMs
      : null;

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h1 className="text-xl sm:text-2xl font-semibold">Interview Results</h1>
        <p className="text-sm text-muted-foreground">Review your responses.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="md:col-span-2">
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Session Summary</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between gap-3">
              <div className="text-sm">
                <div className="font-medium">Completion</div>
                <div className="text-muted-foreground">{completionPct}%</div>
              </div>
              <div className="w-44">
                <Progress value={completionPct} aria-label="Session completion" />
              </div>
            </div>

            <Separator />

            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
              <div className="space-y-1">
                <div className="text-sm text-muted-foreground">Total Questions</div>
                <div className="text-base font-semibold">{total}</div>
              </div>
              <div className="space-y-1">
                <div className="text-sm text-muted-foreground">Answered</div>
                <div className="text-base font-semibold">{answered}</div>
              </div>
              <div className="space-y-1">
                <div className="text-sm text-muted-foreground">Skipped</div>
                <div className="text-base font-semibold">{skipped}</div>
              </div>

              <div className="space-y-1 sm:col-span-2">
                <div className="text-sm text-muted-foreground">Started Time</div>
                <div className="text-sm font-medium">{formatEpochMs(sessionMeta?.startedAtEpochMs)}</div>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <div className="text-sm text-muted-foreground">Finished Time</div>
                <div className="text-sm font-medium">{formatEpochMs(sessionMeta?.finishedAtEpochMs)}</div>
              </div>

              <div className="space-y-1 sm:col-span-2">
                <div className="text-sm text-muted-foreground">Duration</div>
                <div className="text-sm font-medium">{formatDurationMs(durationMs)}</div>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Statistics</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <div className="flex items-center justify-between text-sm">
                <span className="text-muted-foreground">Total</span>
                <span className="font-medium">{total}</span>
              </div>
              <div className="flex items-center justify-between text-sm">
                <span className="text-muted-foreground">Answered</span>
                <span className="font-medium">{answered}</span>
              </div>
              <div className="flex items-center justify-between text-sm">
                <span className="text-muted-foreground">Skipped</span>
                <span className="font-medium">{skipped}</span>
              </div>
              <div className="flex items-center justify-between text-sm">
                <span className="text-muted-foreground">Completion</span>
                <span className="font-medium">{completionPct}%</span>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Question Review</CardTitle>
        </CardHeader>
        <CardContent>
          {total === 0 ? (
            <div className="text-sm text-muted-foreground">No interview data found.</div>
          ) : (
            <div className="space-y-4">
              {summaryQuestions.map((q, idx) => {
                const isAnswered = !q.skipped && String(q.answerText ?? "").trim().length > 0;
                const isSkipped = Boolean(q.skipped);

                const status = isSkipped
                  ? { label: "Skipped", variant: "secondary" }
                  : isAnswered
                    ? { label: "Answered", variant: "default" }
                    : { label: "Unanswered", variant: "outline" };

                return (
                  <div key={q.questionId} className="space-y-2 rounded-lg border p-4">
                    <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-2">
                      <div className="space-y-1">
                        <div className="text-sm text-muted-foreground">Question {idx + 1} of {total}</div>
                        <div className="text-sm font-medium">{q.prompt}</div>
                      </div>
                      <Badge variant={status.variant}>{status.label}</Badge>
                    </div>

                    <div className="space-y-1">
                      <div className="text-xs text-muted-foreground">User Answer</div>
                      <div className="text-sm whitespace-pre-wrap">
                        {isAnswered ? q.answerText : "—"}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Keep consistent with architecture: presentation-only. */}
    </div>
  );
}

